import requests, os, json, time, sys
os.makedirs('/workspace/inputs/cistrome_pages', exist_ok=True)
url='https://db3.cistrome.org/cistrome/samples'
limit=10000
offset=0
for page in range(50):
    out=f'/workspace/inputs/cistrome_pages/page_{page:03d}_{offset}.json'
    if os.path.exists(out) and os.path.getsize(out)>10:
        try:
            data=json.load(open(out))
        except Exception:
            pass
        else:
            samples=data.get('samples',[])
            if not samples:
                break
            offset += len(samples)
            print('cached',page,offset,flush=True)
            continue
    last=None
    for attempt in range(5):
        try:
            r=requests.get(url, params={'limit':limit,'offset':offset}, timeout=60)
            if r.status_code==200:
                data=r.json()
                samples=data.get('samples',[])
                with open(out,'w') as f:
                    json.dump(data,f)
                print('fetched',page,offset,'n',len(samples),'first',samples[0]['id'] if samples else None,'last',samples[-1]['id'] if samples else None,flush=True)
                if not samples:
                    sys.exit(0)
                offset += len(samples)
                break
            else:
                print('status',r.status_code, r.text[:200],flush=True)
        except Exception as e:
            print('err',e,flush=True)
            time.sleep(5)
    else:
        print('failed page',page,offset,flush=True)
        break
    if len(samples)<limit:
        print('done less than limit',offset,flush=True)
        break
